INSERT INTO auditoria (id_usuario, accion, entidad, id_entidad, detalle, comando, fecha) SELECT registrado_por, 'INSERTAR', 'material', id_material, codigo || ' ' || titulo || ' (' || tipo || ', ' || duracion_seg || ' s, ' || formato || ')', 'insMat', fecha_registro FROM material;
INSERT INTO auditoria (id_usuario, accion, entidad, id_entidad, detalle, comando, fecha) SELECT validado_por, 'VALIDAR', 'material', id_material, codigo || ': PENDIENTE -> ' || estado || coalesce(' (' || observacion || ')', ''), 'valMat', fecha_validacion FROM material WHERE validado_por IS NOT NULL;
INSERT INTO auditoria (id_usuario, accion, entidad, id_entidad, detalle, comando, fecha) SELECT creado_por, 'INSERTAR', 'parrilla', id_parrilla, 'Parrilla del ' || fecha || ' (BORRADOR)', 'insPar', fecha_creacion FROM parrilla;
INSERT INTO auditoria (id_usuario, accion, entidad, id_entidad, detalle, comando, fecha) SELECT creado_por, 'PUBLICAR', 'parrilla', id_parrilla, 'Parrilla del ' || fecha || ' publicada', 'pubPar', fecha_publicacion FROM parrilla WHERE estado = 'PUBLICADA';
INSERT INTO auditoria (id_usuario, accion, entidad, id_entidad, detalle, comando, fecha) SELECT registrado_por, 'INSERTAR', 'emision', id_emision, 'Emision ' || estado, 'insEmi', fecha_registro FROM emision;
