-- Datos de demostracion de Canal 11 TVU. Generado a partir de la grilla real del viernes 20-11-2026 (dia 0 = hoy al cargar).
-- Dias -2 y -1: parrillas publicadas y emitidas (mismos programas y horarios, con otros contenidos). Dia 0: la grilla real, publicada y emitida hasta ahora.
-- Dia +1: BORRADOR con materiales pendientes/rechazados (para mostrar la alerta de parrilla en riesgo). No se cargan en la base del curso.
-- DATOS DE DEMOSTRACION (se cargan con ./scripts/ejecutar.sh local --poblar, que BORRA la base local y la vuelve a crear).;
UPDATE parrilla SET estado = 'PUBLICADA', fecha_publicacion = (((((now() AT TIME ZONE 'America/La_Paz')::date) + (-3)) + TIME '17:30')) WHERE fecha = (((now() AT TIME ZONE 'America/La_Paz')::date) + (-2));
UPDATE parrilla SET estado = 'PUBLICADA', fecha_publicacion = (((((now() AT TIME ZONE 'America/La_Paz')::date) + (-2)) + TIME '17:30')) WHERE fecha = (((now() AT TIME ZONE 'America/La_Paz')::date) + (-1));
UPDATE parrilla SET estado = 'PUBLICADA', fecha_publicacion = (((((now() AT TIME ZONE 'America/La_Paz')::date) + (-1)) + TIME '17:30')) WHERE fecha = (((now() AT TIME ZONE 'America/La_Paz')::date) + (0));
UPDATE spot SET estado = 'EMITIDO' WHERE id_bloque IN (SELECT id_bloque FROM emision WHERE estado = 'EMITIDO');
